viewof selectedRawCodes = Inputs.checkbox(rawCodeOptions.map((d) =&gt; d.value), {format: (d) =&gt; rawCodeLabels.get(d) ?? d})









viewof serviceMatchMode = Inputs.radio(["All selected", "Any selected"], {
