  const available = row?.available === true || String(row?.available).toLowerCase() === "true"
  return available && hasNumericValue(row?.facility_count) ? row.facility_count : NaN
}
selectedTotal = characteristicValue("total", "total")
selectedOtp = characteristicValue("otp_status", "otp")
selectedNonOtp = characteristicValue("otp_status", "non_otp")
selectedNonprofit = characteristicValue("ownership", "private_nonprofit")
selectedForprofit = characteristicValue("ownership", "private_forprofit")
selectedGovernment = characteristicValue("ownership", "government")
summaryTile = (label, value) =&gt; html`&lt;div class="metric-tile"&gt;
