)







overviewUsesPuf = overviewMetric === "ownership"
overviewBaseRows = overviewUsesPuf
  ? ownershipPuf.map((d) =&gt; ({
      ...d,
      label: d.ownership,
      plot_value: d.ownership_share
    }))
  : characteristics
      .filter((d) =&gt; d.metric === overviewMetric && d.available)
      .map((d) =&gt; ({...d, plot_value: d.facility_count}))
overviewRows = withTrendSegments(overviewBaseRows)
overviewYLabel = overviewUsesPuf
  ? "Share of classified public-use survey facilities"
