  },
  color: {legend: overviewMetric !== "total"},
  marks: [
    Plot.ruleY([0], {stroke: "#d8d1d4"}),
    Plot.ruleX([2020.5], {stroke: "#5b1f2e", strokeDasharray: "5,4"}),
    Plot.line(overviewRows, {
