Directory ownership tiles use codes printed in the facility listings and appear only when at least 95% of listings are classified. The ownership trend uses the N-SSATS/N-SUMHSS public-use survey files, so it extends farther back but is not used for map filters. Lines break at missing survey years and at the 2020/2021 redesign.



viewof selectedState = Inputs.select(stateOptions, {
  label: "State detail",
  value: "OR",
  format: (abbr) =&gt; stateNameByFips.get(metadata.state_fips[abbr]) ?? abbr
})







mapYearRows = await d3.csv(`data/facility_dashboard_${selectedSurveyYear}.csv`, d3.autoType)
mapIsAvailable = selectionAvailable(selectedSurveyYear)
mapFilteredRows = mapIsAvailable ? mapYearRows.filter(rowPassesShard) : []
mapCounts = d3.rollup(mapFilteredRows, (rows) =&gt; rows.length, (d) =&gt; d.state)
mapPopulationRows = population.filter((d) =&gt; d.survey_year === selectedSurveyYear)
mapStateRows = mapPopulationRows.map((pop) =&gt; {
  const count = mapCounts.get(pop.state) ?? 0
  const rate = pop.population &gt; 0 ? count / pop.population * 100000 : NaN
  return {...pop, count, rate, value: perCapita ? rate : count}
})
mapByFips = new Map(mapStateRows.map((d) =&gt; [String(d.state_fips).padStart(2, "0"), d]))
selectedStateRows = mapFilteredRows.filter((d) =&gt; d.state === selectedState)
stateOtpAvailable = availabilityByKey.get(`${selectedSurveyYear}|service_family|opioid_treatment_program`) === true
stateSplitOwnershipAvailable = ["private_nonprofit", "private_forprofit"].every(
  (value) =&gt; availabilityByKey.get(String(selectedSurveyYear) + "|ownership|" + value) === true
)
stateGovernmentAvailable = [
  "local_government", "state_government", "tribal_government",
  "federal_dod", "federal_other", "federal_ihs", "federal_va"
].every(
  (value) =&gt; availabilityByKey.get(String(selectedSurveyYear) + "|ownership|" + value) === true
)
otpBit = groupBit("service_family", "opioid_treatment_program")
governmentBits = ["local_government", "state_government", "tribal_government", "federal_dod", "federal_other", "federal_ihs", "federal_va"]
  .reduce((mask, value) =&gt; mask | groupBit("ownership", value), 0)
stateOtp = stateOtpAvailable ? selectedStateRows.filter((d) =&gt; (+d.service_family_mask & otpBit) !== 0).length : NaN
stateNonprofit = stateSplitOwnershipAvailable ? selectedStateRows.filter((d) =&gt; (+d.ownership_mask & groupBit("ownership", "private_nonprofit")) !== 0).length : NaN
stateForprofit = stateSplitOwnershipAvailable ? selectedStateRows.filter((d) =&gt; (+d.ownership_mask & groupBit("ownership", "private_forprofit")) !== 0).length : NaN
stateGovernment = stateGovernmentAvailable ? selectedStateRows.filter((d) =&gt; (+d.ownership_mask & governmentBits) !== 0).length : NaN

























































































































mapIsAvailable
  ? Plot.plot({
      width: 980,
      height: 540,
      projection: "albers-usa",
      color: {
        scheme: "purples",
        label: perCapita ? "Facilities per 100,000" : "Facility count",
        legend: true
      },
      marks: [
        Plot.geo(stateFeatures, {
          fill: (feature) =&gt; mapByFips.get(String(feature.id).padStart(2, "0"))?.value ?? 0,
          stroke: "#ffffff",
