            return `${feature.properties.name}\nFacilities: ${fmtInt(row?.count)}\nRate: ${fmtRate(row?.rate)} per 100,000\nFilters: ${activeFilterSummary}`
          }
        }),
        Plot.geo(stateFeatures.filter((feature) =&gt; String(feature.id).padStart(2, "0") === metadata.state_fips[selectedState]), {
          fill: "none",
          stroke: "#5b1f2e",
          strokeWidth: 2.4
        })
      ]
    })
  : html`&lt;div class="data-unavailable"&gt;A selected characteristic is not available for ${yearLabels.get(selectedSurveyYear)}.&lt;/div&gt;`







html`&lt;div class="metric-tile-grid state-detail-grid"&gt;
  ${summaryTile(`${selectedState} facilities`, selectedStateRows.length)}
  ${summaryTile("OTP", stateOtp)}
  ${summaryTile("Non-OTP", stateOtpAvailable ? selectedStateRows.length - stateOtp : NaN)}
  ${summaryTile("Nonprofit", stateNonprofit)}
  ${summaryTile("For-profit", stateForprofit)}
  ${summaryTile("Government", stateGovernment)}
&lt;/div&gt;`









ZIP-based preliminary geography From 2000 onward, current county assignments use ZIP-to-county crosswalks rather than street geocodes. Multi-county ZIPs may be assigned incorrectly.


viewof countyState = Inputs.select(stateOptions, {
  label: "State",
  value: selectedState,
  format: (abbr) =&gt; stateNameByFips.get(metadata.state_fips[abbr]) ?? abbr
})







countyStateFips = metadata.state_fips[countyState]
countyStateRows = mapFilteredRows.filter((d) =&gt; d.state === countyState)
countyAssignedRows = countyStateRows.filter((d) =&gt; String(d.county_fips || "").length === 5)
countyUnassigned = countyStateRows.length - countyAssignedRows.length
countyHigh = countyAssignedRows.filter((d) =&gt; d.geocode_confidence === "high").length
countyFallback = countyAssignedRows.filter((d) =&gt; d.geocode_method === "zip_crosswalk").length
countyCounts = d3.rollup(countyAssignedRows, (rows) =&gt; rows.length, (d) =&gt; String(d.county_fips))
stateCountyFeatures = countyFeatures.filter((feature) =&gt; String(feature.id).padStart(5, "0").startsWith(countyStateFips))
stateCountyCollection = ({type: "FeatureCollection", features: stateCountyFeatures})

































































html`&lt;div class="metric-tile-grid county-metric-grid"&gt;
  ${summaryTile("State facilities", countyStateRows.length)}
  ${summaryTile("County assigned", countyAssignedRows.length)}
  ${summaryTile("High confidence", countyHigh)}
  ${summaryTile("ZIP fallback", countyFallback)}
  ${summaryTile("Unassigned", countyUnassigned)}
&lt;/div&gt;`







mapIsAvailable && countyAssignedRows.length
  ? Plot.plot({
      width: 980,
      height: 600,
      projection: {type: "mercator", domain: stateCountyCollection, inset: 12},
      color: {scheme: "purples", label: "Facility count", legend: true},
      marks: [
        Plot.geo(stateCountyFeatures, {
          fill: (feature) =&gt; countyCounts.get(String(feature.id).padStart(5, "0")) ?? 0,
          stroke: "#ffffff",
          strokeWidth: 0.7,
          title: (feature) =&gt; `${feature.properties.name}\nFacilities: ${fmtInt(countyCounts.get(String(feature.id).padStart(5, "0")) ?? 0)}\n${yearLabels.get(selectedSurveyYear)}\nFilters: ${activeFilterSummary}`
        })
      ]
    })
  : html`&lt;div class="data-unavailable"&gt;No county-assigned facilities are available for this state, year, and filter selection.&lt;/div&gt;`










