  label: "End year",
  value: d3.max(surveyYears),
  format: (d) =&gt; yearLabels.get(d)
})







trendMetrics = [
  "filtered", "otp", "nonprofit", "forprofit", "government",
  "outpatient", "residential", "hospital"
]
viewof trendMetric = Inputs.select(trendMetrics, {
  label: "Metric",
  value: "filtered",
  format: (value) =&gt; ({
    filtered: "Facilities matching filters",
    otp: "OTP",
