overlayOptions = [
  "US",
  ...regionOptions.map((d) =&gt; `Region:${d}`),
  ...stateOptions.map((d) =&gt; `State:${d}`)
]
overlayLabel = (value) =&gt; {
  if (value === "US") return "United States"
  const [kind, name] = value.split(":")
  return kind === "Region" ? `${name} region` : (stateNameByFips.get(metadata.state_fips[name]) ?? name)
}
viewof selectedOverlays = Inputs.select(overlayOptions, {
  label: "Geographies (maximum three)",
  value: ["US"],
  multiple: true,
  size: 5,
  format: overlayLabel
})
























comparisonYearLo = Math.min(comparisonStartYear, comparisonEndYear)
comparisonYearHi = Math.max(comparisonStartYear, comparisonEndYear)
comparisonYears = surveyYears.filter((year) =&gt; year &gt;= comparisonYearLo && year &lt;= comparisonYearHi)
overlaySelection = normalizeMulti(selectedOverlays).slice(0, 3)
comparisonUsesRaw = rawCodeSelection.length &gt; 0
comparisonRows = comparisonUsesRaw
  ? (await Promise.all(comparisonYears.map((year) =&gt; d3.csv(`data/facility_dashboard_${year}.csv`, d3.autoType)))).flat()
  : filterCube.filter((d) =&gt; d.survey_year &gt;= comparisonYearLo && d.survey_year &lt;= comparisonYearHi)
rowWeight = (row) =&gt; comparisonUsesRaw ? 1 : (+row.facility_count || 0)
metricDefinition = ({
  otp: ["service_family", ["opioid_treatment_program"]],
  nonprofit: ["ownership", ["private_nonprofit"]],
  forprofit: ["ownership", ["private_forprofit"]],
  government: ["ownership", ["local_government", "state_government", "tribal_government", "federal_dod", "federal_other", "federal_ihs", "federal_va"]],
  outpatient: ["setting", ["outpatient"]],
  residential: ["setting", ["residential"]],
  hospital: ["setting", ["hospital_inpatient"]]
})[trendMetric]
trendMetricAvailable = (year) =&gt; {
  if (!metricDefinition) return true
  const [group, values] = metricDefinition
  const checks = values.map((value) =&gt; availabilityByKey.get(String(year) + "|" + group + "|" + value) === true)
  return group === "ownership" ? checks.every(Boolean) : checks.some(Boolean)
}
trendMetricPasses = (row) =&gt; {
  if (!metricDefinition) return true
  const [group, values] = metricDefinition
  const wanted = values.reduce((mask, value) =&gt; mask | groupBit(group, value), 0)
  return ((+row[`${group}_mask`] || 0) & wanted) !== 0
}
comparisonPasses = (row) =&gt; (
  (comparisonUsesRaw ? rowPassesShard(row) : rowPassesHarmonized(row)) &&
  trendMetricPasses(row)
)
geographyRows = (rows, geography) =&gt; {
  if (geography === "US") return rows
  const [kind, value] = geography.split(":")
  return kind === "Region"
    ? rows.filter((d) =&gt; d.census_region === value)
    : rows.filter((d) =&gt; d.state === value)
}
geographyPopulation = (year, geography) =&gt; {
  const rows = population.filter((d) =&gt; d.survey_year === year)
  if (geography === "US") return d3.sum(rows, (d) =&gt; d.population)
  const [kind, value] = geography.split(":")
  if (kind === "State") return populationByYearState.get(`${year}|${value}`)?.population ?? NaN
  const statesInRegion = new Set(
