    d.year &gt;= tsYearLo &&
    d.year &lt;= tsYearHi &&
    tsChosenGenerics.includes(d.moud_generic) &&
    (tsUtilizationType === "All" || d.utilization_type === tsUtilizationType)
  )
  if (!common) return false
  if (!tableStates) return true
  return tableStates.has(d.state_abbr)
})

ndcAgg = Array.from(d3.group(ndcRowsFiltered, (d) =&gt; d.ndc), ([ndc, rows]) =&gt; ({
  ndc,
  scripts: d3.sum(rows, (r) =&gt; r.scripts),
  total_reimb: d3.sum(rows, (r) =&gt; r.total_reimb),
  medicaid_reimb: d3.sum(rows, (r) =&gt; r.medicaid_reimb),
  nonmedicaid_reimb: d3.sum(rows, (r) =&gt; r.nonmedicaid_reimb)
}))

searchText = (ndcSearch || "").toLowerCase().trim()
ndcSearched = searchText ? ndcAgg.filter((d) =&gt; d.ndc.toLowerCase().includes(searchText)) : ndcAgg
sortMult = ndcSortDir === "Ascending" ? 1 : -1
ndcSorted = ndcSearched.slice().sort((a, b) =&gt; {
  const av = a[ndcSortCol]
  const bv = b[ndcSortCol]
  if (ndcSortCol === "ndc") return sortMult * String(av).localeCompare(String(bv))
  return sortMult * ((av || 0) - (bv || 0))
})

ndcVisible = ndcSorted.slice(0, ndcRowLimit)

ndcTableSummary = html`&lt;div class="dashboard-card compact"&gt;
  &lt;strong&gt;${fmtInt(ndcSearched.length)}&lt;/strong&gt; filtered NDC rows (${fmtInt(ndcAgg.length)} total in selection)
  &lt;p class="muted"&gt;Table filters follow the time-series control panel.&lt;/p&gt;
&lt;/div&gt;`

ndcTable = Inputs.table(ndcVisible, {
  columns: ["ndc", "scripts", "total_reimb", "medicaid_reimb", "nonmedicaid_reimb"],
  header: {
    ndc: "NDC",
    scripts: "Prescriptions",
    total_reimb: "Total Reimbursed",
    medicaid_reimb: "Medicaid Reimbursed",
    nonmedicaid_reimb: "Non-Medicaid Reimbursed"
  },
  format: {
    scripts: (v) =&gt; fmtInt(v),
    total_reimb: (v) =&gt; fmtMoney(v),
    medicaid_reimb: (v) =&gt; fmtMoney(v),
    nonmedicaid_reimb: (v) =&gt; fmtMoney(v)
  },
  rows: ndcRowLimit
})

ndcDownloadLink = {
  const csv = d3.csvFormat(ndcSorted)
  const blob = new Blob([csv], {type: "text/csv;charset=utf-8"})
  const href = URL.createObjectURL(blob)
  return html`&lt;a class="btn btn-primary" href="${href}" download="moud_ndc_filtered.csv"&gt;Download Filtered NDC CSV&lt;/a&gt;`
}

3 Standard Synthetic Control
If we match only on the pre-treatment outcome path (something worth being careful about; check out this cherry-picking article), the standard synthetic control problem chooses donor weights that make the pre-treatment treated outcome look as close as possible to the weighted donor outcome path:
\[
\hat{w}
=
\arg\min_{w\in\Delta_J}
\sum_{t=1}^{T_0}
\left(
Y_{1t}
-
\sum_{j=2}^{J+1} w_j Y_{jt}
\right)^2.
\]
In matrix form, define
\[
Y_{1,\text{pre}}
=
\begin{bmatrix}
Y_{11}\\
\vdots\\
Y_{1T_0}
\end{bmatrix},
\qquad
Y_{0,\text{pre}}
=
\begin{bmatrix}
Y_{21} & \cdots & Y_{J+1,1}\\
\vdots & \ddots & \vdots\\
Y_{2T_0} & \cdots & Y_{J+1,T_0}
\end{bmatrix}.
\]
Then the same problem is
\[
\hat{w}
=
\arg\min_{w\in\Delta_J}
\left\|
Y_{1,\text{pre}}
-
Y_{0,\text{pre}}w
\right\|^2.
\]
With the dimensions written underneath, something I tend to do since my econometrics class with George Evans who always paid particular attention to this, the implementation object is
\[
\hat{w}
=
\arg\min_{w\in\Delta_J}
\left\|
\underset{T_0\times 1}{Y_{1,\text{pre}}}
-
\underset{T_0\times J}{Y_{0,\text{pre}}}
\underset{J\times 1}{w}
\right\|^2.
\]
Once we have \(\hat{w}\), the period-specific treatment effect estimate is
\[
\hat{\tau}_{1t}
=
Y_{1t}
-
\sum_{j=2}^{J+1}
\hat{w}_jY_{jt},
\qquad
t=T_0+1,\dots,T.
\]
The average post-treatment effect is
\[
\hat{\tau}
=
\frac{1}{T_1}
\sum_{t=T_0+1}^{T}
\hat{\tau}_{1t}.
\]
From there, one can use placebo inference or related work on t-statistics for SCM.

6 Normalization
One last thing that matters more than I initially wanted it to: the outcomes need to be put on comparable footing. Otherwise, stable level differences across units or outcomes can end up doing a lot of work in the optimization problem. The math is not being mean; it is just doing exactly what we asked it to do.
The normalization used in these papers is pretty simple. They use demeaned outcomes, where each unit-outcome series is centered by its own pre-treatment mean:
\[
\dot{Y}_{itk}
=
Y_{itk}
-
\frac{1}{T_0}
\sum_{s=1}^{T_0}
Y_{isk}.
\]
So rather than matching on the raw level of each outcome, we are matching on movement relative to that unit’s own pre-period average. This is also why it is sometimes described as an intercept-shifted synthetic control. We let units differ by a stable level difference, but still ask the synthetic control to track the treated unit’s dynamics.
In practice, this means the concatenation or averaging step above is done with \(\dot{Y}_{itk}\) instead of \(Y_{itk}\). Then, when we construct the counterfactual for a specific outcome, we can add the treated unit’s pre-treatment mean back in:
\[
\hat{Y}_{1tk}(0)
=
\bar{Y}_{1\cdot k}
+
\sum_{j=2}^{J+1}
\hat{w}_j\dot{Y}_{jtk},
\qquad
\bar{Y}_{1\cdot k}
=
\frac{1}{T_0}
\sum_{s=1}^{T_0}
Y_{1sk}.
\]
The short version: before estimating the weights, subtract each unit’s pre-treatment average for each outcome. This is not a separate research design choice so much as a practical step that keeps the multiple outcomes from turning into a contest of levels.
